import{_ as r,y as o,a,o as i,a2 as t,D as s}from"./chunks/framework.DCcmcJcL.js";const m=JSON.parse('{"title":"Search Engines","description":"","frontmatter":{},"headers":[],"relativePath":"configure/search-engines.md","filePath":"configure/search-engines.md","lastUpdated":1789319704000}'),h={name:"configure/search-engines.md"};function g(c,e,l,d,u,p){const n=o("ImagePopup");return i(),a("div",null,[e[0]||(e[0]=t('<h1 id="search-engines" tabindex="-1">Search Engines <a class="header-anchor" href="#search-engines" aria-label="Permalink to &quot;Search Engines&quot;">​</a></h1><p>Product search on the storefront and in the admin runs on the database by default. For a large catalog you can connect an Elasticsearch cluster and choose where it is used.</p><p>Go to <strong>Configure &gt;&gt; Search Engines</strong>. It is available on the current version of Bagisto; on Bagisto 2.4 the same choices are the <strong>Search Engine</strong>, <strong>Admin Search Mode</strong> and <strong>Storefront Search Mode</strong> settings in the <strong>Search</strong> section under <strong>Configure &gt;&gt; Catalog &gt;&gt; Products</strong>.</p><h2 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h2>',4)),s(n,{src:"/images/configure/search-engines-general.png",alt:"Search Engines General Settings"}),e[1]||(e[1]=t('<h3 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h3><p><strong>Enable External Search Engine:</strong> Turn this on to use the engine chosen below. While it is off, every search runs on the database whatever the other settings say.</p><p><strong>Default Search Engine:</strong> <strong>Database</strong> or <strong>Elasticsearch</strong>. This is the engine used wherever a search mode below is left on <strong>Use Default</strong>.</p><h3 id="products" tabindex="-1">Products <a class="header-anchor" href="#products" aria-label="Permalink to &quot;Products&quot;">​</a></h3><p><strong>Admin Search Mode:</strong> The engine behind the header search, the listing grids and the other searches in the admin panel.</p><p><strong>Storefront Search Mode:</strong> The engine behind category pages, the search page and the other searches on the storefront.</p><p>Each can be <strong>Use Default</strong>, <strong>Database</strong> or <strong>Elasticsearch</strong>, so you can, for example, keep the admin on the database while the storefront searches Elasticsearch.</p><p>Click <strong>Save Configuration</strong>.</p><h2 id="elasticsearch" tabindex="-1">Elasticsearch <a class="header-anchor" href="#elasticsearch" aria-label="Permalink to &quot;Elasticsearch&quot;">​</a></h2>',9)),s(n,{src:"/images/configure/search-engines-elastic.png",alt:"Elasticsearch Settings"}),e[2]||(e[2]=t('<p>These settings are used only when a search mode is set to Elasticsearch.</p><p><strong>Authentication:</strong> How the cluster is reached and signed in to. Only the fields the chosen method needs are shown:</p><ul><li><strong>No authentication</strong> — just the <strong>Hosts</strong>.</li><li><strong>Username and password</strong> — <strong>Hosts</strong>, <strong>Username</strong> and <strong>Password</strong>.</li><li><strong>API key</strong> — <strong>Hosts</strong> and <strong>API Key</strong>.</li><li><strong>Elastic Cloud with API key</strong> — <strong>Cloud ID</strong> and <strong>API Key</strong>.</li><li><strong>Elastic Cloud with username and password</strong> — <strong>Cloud ID</strong>, <strong>Username</strong> and <strong>Password</strong>.</li></ul><p><strong>Hosts:</strong> Where the cluster is reached, such as <code>http://localhost:9200</code>. Separate several hosts with a comma. Leave it empty to use the value from the server&#39;s environment file.</p><p><strong>Index Prefix:</strong> Added to the front of every index name, so several stores can share one cluster.</p><p><strong>Minimum Query Length</strong> and <strong>Maximum Query Length:</strong> The shortest and longest search term the storefront search box accepts.</p><h3 id="testing-the-connection" tabindex="-1">Testing the connection <a class="header-anchor" href="#testing-the-connection" aria-label="Permalink to &quot;Testing the connection&quot;">​</a></h3><p>The <strong>Connection</strong> row has a <strong>Test Connection</strong> button. Click it after saving to check the cluster from the server&#39;s side. The result tells you whether the engine <strong>is available</strong>, <strong>did not answer</strong>, <strong>rejected the credentials</strong>, answered but <strong>is not a supported Elasticsearch server</strong>, or <strong>is not configured</strong>.</p><h3 id="building-the-index" tabindex="-1">Building the index <a class="header-anchor" href="#building-the-index" aria-label="Permalink to &quot;Building the index&quot;">​</a></h3><p>A cluster only returns products that have been indexed. After connecting it for the first time, ask whoever manages the server to run the product indexer for the search engine; it also runs on the queue whenever a product is saved, so the index keeps itself current afterwards.</p>',10))])}const _=r(h,[["render",g]]);export{m as __pageData,_ as default};
